import { McpAgent } from "agents/mcp";
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";

import { HEIGHT, ROOM_NAME, SIZE, WIDTH, WRITE_SKIP } from "./grid-room";

const GRID_URI = "grid://current";

// The MCP interface. Each MCP session runs in its own GridMCP DO
// instance (managed by McpAgent), but all of them proxy mutations to
// the singleton GridRoom — so an MCP tool is literally a caller of
// the same RPC that the HTTP route uses.

export class GridMCP extends McpAgent<Env> {
  server = new McpServer({
    name: "mcp-pixel-grid",
    version: "0.2.0",
  });

  async init(): Promise<void> {
    this.server.registerResource(
      "grid",
      GRID_URI,
      {
        title: "Pixel grid",
        description:
          `The current ${WIDTH}×${HEIGHT} grid as ${HEIGHT} lines of ${WIDTH} ` +
          `characters each, separated by '\\n'. '0' = white, '1' = black. ` +
          `The format matches the 'bits' argument of the write tool, so a ` +
          `slice of this resource can be passed straight back in.`,
        mimeType: "text/plain",
      },
      async (uri) => {
        const bytes = await this.room().snapshot();
        return {
          contents: [
            {
              uri: uri.href,
              mimeType: "text/plain",
              text: bytesToGridText(bytes),
            },
          ],
        };
      },
    );

    this.server.registerTool(
      "clear",
      {
        description: "Clear the grid (set every pixel to white).",
        inputSchema: {},
      },
      async () => {
        const changed = await this.room().clear();
        return {
          content: [{ type: "text", text: `cleared ${changed} pixel(s)` }],
        };
      },
    );

    this.server.registerTool(
      "write",
      {
        description:
          `Write a run of pixels starting at a linear address. ` +
          `The grid is row-major: address = y * ${WIDTH} + x, ranging 0..${SIZE - 1}. ` +
          `The 'bits' string has one character per cell: ` +
          `'1' = black, '0' = white, '${WRITE_SKIP}' = leave unchanged. ` +
          `Writes wrap across rows. ` +
          `Example: offset=0, bits="11111111" blackens pixels (0,0)..(7,0).`,
        inputSchema: {
          offset: z.number().int().min(0).max(SIZE),
          bits: z
            .string()
            .regex(
              new RegExp(`^[01\\${WRITE_SKIP}]*$`),
              `bits must contain only '0', '1', or '${WRITE_SKIP}'`,
            ),
        },
      },
      async ({ offset, bits }) => {
        const changed = await this.room().writeBits(offset, bits);
        return {
          content: [{ type: "text", text: `wrote ${changed} pixel(s)` }],
        };
      },
    );
  }

  // A stub to the singleton GridRoom. Not "the MCP server's state" —
  // the MCP server is stateless here; state lives in the Room.
  private room(): DurableObjectStub<import("./grid-room").GridRoom> {
    const id = this.env.ROOM.idFromName(ROOM_NAME);
    return this.env.ROOM.get(id) as DurableObjectStub<
      import("./grid-room").GridRoom
    >;
  }
}

// Render a row-major byte grid as HEIGHT lines of WIDTH characters,
// where each character is '0' (white) or '1' (black).
function bytesToGridText(bytes: Uint8Array): string {
  const rows: string[] = [];
  for (let y = 0; y < HEIGHT; y++) {
    let row = "";
    for (let x = 0; x < WIDTH; x++) {
      row += bytes[y * WIDTH + x] ? "1" : "0";
    }
    rows.push(row);
  }
  return rows.join("\n");
}

import { DurableObject } from "cloudflare:workers";

// The single source of truth. Every interface — HTTP click, WebSocket,
// MCP tool — converges on the RPC methods below.
//
// This DO is addressed as a singleton via idFromName("room"). State
// lives in a Uint8Array, persisted to ctx.storage. Live updates fan
// out to every subscribed browser via hibernatable WebSockets.

export const WIDTH = 32;
export const HEIGHT = 32;
export const SIZE = WIDTH * HEIGHT;
export const ROOM_NAME = "room";

// Skip character for writeBits: leaves a cell untouched.
export const WRITE_SKIP = ".";

export type Pixel = { x: number; y: number; v: 0 | 1 };

const STORAGE_KEY = "grid";

export class GridRoom extends DurableObject<Env> {
  private grid: Uint8Array;
  private loaded: Promise<void>;

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    this.grid = new Uint8Array(WIDTH * HEIGHT);
    this.loaded = this.hydrate();
  }

  private async hydrate(): Promise<void> {
    const stored = await this.ctx.storage.get<ArrayBuffer>(STORAGE_KEY);
    // Drop persisted state of a different size (e.g. after a grid resize).
    if (stored && stored.byteLength === WIDTH * HEIGHT) {
      this.grid = new Uint8Array(stored);
    }
  }

  // ─── RPC: the contract every interface uses ──────────────────────

  async snapshot(): Promise<Uint8Array> {
    await this.loaded;
    return new Uint8Array(this.grid);
  }

  async toggle(x: number, y: number): Promise<Pixel | null> {
    await this.loaded;
    if (!inBounds(x, y)) return null;
    const i = y * WIDTH + x;
    const v: 0 | 1 = this.grid[i] ? 0 : 1;
    this.grid[i] = v;
    const p: Pixel = { x, y, v };
    await this.persist();
    this.broadcast([p]);
    return p;
  }

  async setPixels(pixels: Pixel[]): Promise<number> {
    await this.loaded;
    const applied: Pixel[] = [];
    for (const p of pixels) {
      if (!inBounds(p.x, p.y)) continue;
      const v: 0 | 1 = p.v ? 1 : 0;
      this.grid[p.y * WIDTH + p.x] = v;
      applied.push({ x: p.x, y: p.y, v });
    }
    if (applied.length) {
      await this.persist();
      this.broadcast(applied);
    }
    return applied.length;
  }

  async clear(): Promise<number> {
    await this.loaded;
    const diff: Pixel[] = [];
    for (let i = 0; i < this.grid.length; i++) {
      if (this.grid[i]) {
        diff.push({ x: i % WIDTH, y: Math.floor(i / WIDTH), v: 0 });
      }
    }
    if (!diff.length) return 0;
    this.grid.fill(0);
    await this.persist();
    this.broadcast(diff);
    return diff.length;
  }

  // Write a run of bits starting at a linear address. Characters:
  //   '1' → black, '0' → white, '.' (WRITE_SKIP) → leave cell unchanged.
  // Returns the count of cells that actually changed.
  async writeBits(offset: number, bits: string): Promise<number> {
    await this.loaded;
    if (!Number.isInteger(offset) || offset < 0 || offset > SIZE) {
      throw new Error(`invalid offset: ${offset} (must be 0..${SIZE})`);
    }
    if (offset + bits.length > SIZE) {
      throw new Error(
        `write of ${bits.length} bits at offset ${offset} exceeds grid size ${SIZE}`,
      );
    }
    const diff: Pixel[] = [];
    for (let i = 0; i < bits.length; i++) {
      const c = bits[i];
      if (c === WRITE_SKIP) continue;
      if (c !== "0" && c !== "1") {
        throw new Error(
          `invalid bit char at index ${i}: ${JSON.stringify(c)} ` +
            `(expected "0", "1", or "${WRITE_SKIP}")`,
        );
      }
      const v: 0 | 1 = c === "1" ? 1 : 0;
      const pos = offset + i;
      if (this.grid[pos] === v) continue;
      this.grid[pos] = v;
      diff.push({ x: pos % WIDTH, y: Math.floor(pos / WIDTH), v });
    }
    if (diff.length) {
      await this.persist();
      this.broadcast(diff);
    }
    return diff.length;
  }

  // ─── HTTP interface (browser click + curl) ───────────────────────

  async fetch(req: Request): Promise<Response> {
    const url = new URL(req.url);

    if (url.pathname === "/ws" && req.headers.get("upgrade") === "websocket") {
      const [client, server] = Object.values(new WebSocketPair());
      this.ctx.acceptWebSocket(server); // hibernation API
      return new Response(null, { status: 101, webSocket: client });
    }

    if (url.pathname === "/api/grid" && req.method === "GET") {
      const buf = await this.snapshot();
      return new Response(buf.buffer as ArrayBuffer, {
        headers: { "content-type": "application/octet-stream" },
      });
    }

    if (url.pathname === "/api/toggle" && req.method === "POST") {
      const { x, y } = (await req.json()) as { x: number; y: number };
      const p = await this.toggle(x, y);
      if (!p) return Response.json({ error: "out of bounds" }, { status: 400 });
      return Response.json(p);
    }

    if (url.pathname === "/api/set-matrix" && req.method === "POST") {
      const body = (await req.json()) as {
        pixels: Array<[number, number, number] | Pixel>;
      };
      const list: Pixel[] = body.pixels.map((p) =>
        Array.isArray(p)
          ? { x: p[0], y: p[1], v: (p[2] ? 1 : 0) as 0 | 1 }
          : p,
      );
      const applied = await this.setPixels(list);
      return Response.json({ applied });
    }

    if (url.pathname === "/api/clear" && req.method === "POST") {
      const cleared = await this.clear();
      return Response.json({ cleared });
    }

    return new Response("not found", { status: 404 });
  }

  // ─── Hibernatable WebSocket hooks ────────────────────────────────
  // Browsers are read-only subscribers: they connect, receive diffs,
  // close. No incoming messages expected.

  async webSocketMessage(_ws: WebSocket, _msg: string | ArrayBuffer) {}

  async webSocketClose(
    ws: WebSocket,
    code: number,
    _reason: string,
    _wasClean: boolean,
  ) {
    try {
      ws.close(code);
    } catch {}
  }

  // ─── internals ───────────────────────────────────────────────────

  private async persist(): Promise<void> {
    await this.ctx.storage.put(STORAGE_KEY, this.grid.buffer.slice(0));
  }

  private broadcast(diff: Pixel[]): void {
    const msg = JSON.stringify(diff);
    for (const ws of this.ctx.getWebSockets()) {
      try {
        ws.send(msg);
      } catch {}
    }
  }
}

function inBounds(x: number, y: number): boolean {
  return (
    Number.isInteger(x) &&
    Number.isInteger(y) &&
    x >= 0 &&
    x < WIDTH &&
    y >= 0 &&
    y < HEIGHT
  );
}

import { GridMCP } from "./grid-mcp";
import { GridRoom, ROOM_NAME } from "./grid-room";

// Re-export the DO classes so the Workers runtime can find them.
export { GridMCP, GridRoom };

// The router. Three interfaces, one Worker.
//
//   /mcp         → GridMCP  (per-session DO, official MCP SDK over
//                             streamable HTTP, handled by agents)
//   /api/*, /ws  → GridRoom (singleton DO, owns the pixel state)
//   everything else → static HTML from ./public

export default {
  async fetch(req: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(req.url);

    if (url.pathname === "/mcp" || url.pathname.startsWith("/mcp/")) {
      return GridMCP.serve("/mcp", { binding: "MCP" }).fetch(req, env, ctx);
    }

    if (url.pathname.startsWith("/api/") || url.pathname === "/ws") {
      const id = env.ROOM.idFromName(ROOM_NAME);
      return env.ROOM.get(id).fetch(req);
    }

    return env.ASSETS.fetch(req);
  },
} satisfies ExportedHandler<Env>;

// Stub for the `ai` SDK. The `agents` package has an optional dynamic
// import of `ai` on an elicitation code path we don't use here. We
// alias it to this stub via wrangler.jsonc → "alias" so the bundle
// resolves without pulling in the real package.
export function jsonSchema(): never {
  throw new Error(
    "'ai' SDK not bundled. Install the 'ai' package if you want MCP elicitation support.",
  );
}

#!/usr/bin/env python3
"""
Compile a 2D drawing operation into a list of 1D write ops for the
pixel-grid MCP server.

This script is a pure translator: it reads a 2D description, emits a
JSON plan, and exits. It does not touch the network. The caller (your
agent) is responsible for running each op as a pixel-grid `write` tool
call.

Output shape:

    { "ops": [ { "offset": <int>, "bits": "<01.-string>" }, ... ] }

Each op maps to one `write(offset, bits)` MCP call. The grid is 32x32
row-major: offset = y * 32 + x. `.` in `bits` leaves the cell unchanged.

Subcommands:

    plan.py rect  X Y W H           Filled W x H rectangle at (X, Y).
    plan.py frame X Y W H           1-pixel outline of a W x H rect;
                                     interior preserved via `.` skips.
    plan.py bitmap X Y              Read rows from stdin, one per line,
                                     each containing only '0', '1', or '.'.
                                     Top-left placed at (X, Y).

Coordinates and dimensions may be negative or exceed the grid; the
plan is clipped to 0..31 on both axes. Out-of-bounds rows/columns are
dropped silently.
"""

import json
import sys

WIDTH = 32
HEIGHT = 32


def ops_from_rows(x: int, y: int, rows: list[str]) -> list[dict]:
    """Clip rows to the grid and emit ONE op per surviving row.

    Per-row is deliberate: packing a shape into a single long bits
    string requires 2D-through-1D padding that makes the write
    payload mostly `.` repetition — exactly the pattern an LLM is
    likely to mis-transcribe. Per-row keeps every `bits` value at
    most WIDTH chars, with each call carrying a distinct offset, so
    the emission stays reliable and a dropped row is visible.
    """
    ops: list[dict] = []
    for i, bits in enumerate(rows):
        py = y + i
        if py < 0 or py >= HEIGHT:
            continue

        # Horizontal clip.
        px = x
        if px < 0:
            bits = bits[-px:]
            px = 0
        if px >= WIDTH:
            continue
        if px + len(bits) > WIDTH:
            bits = bits[: WIDTH - px]
        if not bits:
            continue

        ops.append({"offset": py * WIDTH + px, "bits": bits})
    return ops


def cmd_rect(x: int, y: int, w: int, h: int) -> list[dict]:
    if w <= 0 or h <= 0:
        return []
    return ops_from_rows(x, y, ["1" * w] * h)


def cmd_frame(x: int, y: int, w: int, h: int) -> list[dict]:
    if w <= 0 or h <= 0:
        return []
    if h == 1:
        return ops_from_rows(x, y, ["1" * w])
    if w == 1:
        return ops_from_rows(x, y, ["1"] * h)
    top = "1" * w
    mid = "1" + "." * (w - 2) + "1"
    return ops_from_rows(x, y, [top, *([mid] * (h - 2)), top])


def cmd_bitmap(x: int, y: int) -> list[dict]:
    rows = [line.rstrip("\n") for line in sys.stdin]
    while rows and not rows[-1]:
        rows.pop()
    if not rows:
        return []
    for i, row in enumerate(rows):
        bad = [c for c in row if c not in "01."]
        if bad:
            sys.exit(
                f"row {i}: unexpected character {bad[0]!r} "
                f"(bitmap cells must be '0', '1', or '.')"
            )
    return ops_from_rows(x, y, rows)


def main() -> None:
    argv = sys.argv[1:]
    if not argv:
        sys.exit("usage: plan.py <rect|frame|bitmap> ...")
    cmd, *rest = argv

    try:
        if cmd in ("rect", "frame"):
            if len(rest) != 4:
                sys.exit(f"usage: plan.py {cmd} X Y W H")
            x, y, w, h = (int(v) for v in rest)
            ops = cmd_rect(x, y, w, h) if cmd == "rect" else cmd_frame(x, y, w, h)
        elif cmd == "bitmap":
            if len(rest) != 2:
                sys.exit("usage: plan.py bitmap X Y  (rows from stdin)")
            x, y = (int(v) for v in rest)
            ops = cmd_bitmap(x, y)
        else:
            sys.exit(f"unknown command: {cmd!r}")
    except ValueError as e:
        sys.exit(f"bad integer argument: {e}")

    json.dump({"ops": ops}, sys.stdout, indent=2)
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
